import { Component, AfterViewInit, ViewChild } from '@angular/core';
import { WsdataService } from '../wsdata.service';
import { NgForm } from '@angular/forms';
import { indexTracker } from '../tools';

@Component({
    selector: 'app-settings',
    templateUrl: './settings.component.html',
    styleUrls: ['./settings.component.less']
})
export class SettingsComponent implements AfterViewInit {

    @ViewChild('settingsForm', {static: false}) public settingsForm: NgForm;
    @ViewChild('alarmSettingsForm', {static: false}) public alarmSettingsForm: NgForm;

    public settingsData = this.wsData.settingsData;
    public indexTracker = indexTracker;

    newdata(): void {
        if (this.settingsForm.form.pristine && this.alarmSettingsForm.form.pristine) {
            this.settingsData = this.wsData.copySettings();
        }
    }

    constructor(public wsData: WsdataService) {
        this.wsData.subscribeNewData(() => this.newdata());
    }

    ngAfterViewInit(): void {
        this.newdata();
    }

    resetForm(): void {
        this.settingsForm.form.markAsPristine();
        this.alarmSettingsForm.form.markAsPristine();
        this.newdata();
    }

    sendForm(): void {
        this.wsData.readSettings(this.settingsData);
        this.wsData.sendSet();
        this.settingsForm.form.markAsPristine();
        this.alarmSettingsForm.form.markAsPristine();
    }
}
