import { Component, AfterContentInit, ViewChild } from '@angular/core';
import { NgForm } from '@angular/forms';
import { WsdataService } from '../wsdata.service';
import { Router } from '@angular/router';

@Component({
    selector: 'app-editclock',
    templateUrl: './editclock.component.html',
    styleUrls: ['./editclock.component.less']
})
export class EditClockComponent implements AfterContentInit {
    @ViewChild('settingsForm', {static: false}) public settingsForm: NgForm;
    public clockLabel = '';
    public clockStyle = 0;
    public dateLocale = 0;

    constructor(public wsData: WsdataService,  private router: Router) {
        this.clockLabel = this.wsData.clockData.label;
        this.wsData.subscribeNewData(() => this.newdata());
        this.copyData();
    }

    newdata(): void {
        if (this.settingsForm.form.pristine) {
            this.copyData();
        }
    }

    copyData(): void {
        this.clockLabel = this.wsData.clockData.label;
        this.clockStyle = this.wsData.clockData.style;
        this.dateLocale = this.wsData.clockData.dateLocale;
    }

    ngAfterContentInit(): void {

    }

    dataApply(): void {
        this.wsData.clockData.label = this.clockLabel;
        this.wsData.clockData.style = this.clockStyle;
        this.wsData.clockData.dateLocale = this.dateLocale;
        this.wsData.layoutData.dirty = 1;
        this.router.navigate(['/edit']);
    }

    dataCancel(): void {
        this.router.navigate(['/edit']);
    }
}
